#!/usr/bin/env python3
# Cut each full FreeSerif and FreeSans font in font-sources, which are from GNU
# FreeFont (https://www.gnu.org/software/freefont/), into small WOFF2 files in
# static/fonts, one per group of characters, and write assets/fonts.css to
# declare them. A browser downloads a file only when a page has a character in
# the file's unicode-range, so a page in English never downloads the Cyrillic
# file. Characters outside all the groups are drawn with the visitor's fonts.
# Needs `pip install fonttools brotli`. Run from the repository root.
from fontTools import subset
from fontTools.ttLib import TTFont

# The characters in each group, written as a CSS unicode-range.
GROUPS = {
    # Enough for English and most Western European languages, e.g. Swedish
    "latin": "U+0000-00FF, U+2000-20CF",
    # The other Latin letters, e.g. in Polish or Vietnamese, and accents
    "latin-ext": "U+0100-036F, U+1E00-1EFF",
    "greek": "U+0370-03FF, U+1F00-1FFF",
    "cyrillic": "U+0400-052F",
    # Arrows, mathematical operators and shapes
    "symbols": "U+2100-27FF",
}

# The font files to cut, and the family, weight and style the CSS gives them
FONTS = [
    ("FreeSerif", "FreeSerif", "normal", "normal"),
    ("FreeSerifBold", "FreeSerif", "bold", "normal"),
    ("FreeSerifItalic", "FreeSerif", "normal", "italic"),
    ("FreeSerifBoldItalic", "FreeSerif", "bold", "italic"),
    ("FreeSans", "FreeSans", "normal", "normal"),
    ("FreeSansBold", "FreeSans", "bold", "normal"),
    ("FreeSansOblique", "FreeSans", "normal", "oblique"),
    ("FreeSansBoldOblique", "FreeSans", "bold", "oblique"),
]

css = "/* Generated by .github/scripts/subset-fonts.py. Don't edit by hand. */\n"
for name, family, weight, style in FONTS:
    for group, unicode_range in GROUPS.items():
        # Keeping the timestamp means an unchanged font gives an unchanged file.
        font = TTFont(f"font-sources/{name}.woff", recalcTimestamp=False)
        wanted = set(subset.parse_unicodes(unicode_range))
        if not wanted & font.getBestCmap().keys():
            continue
        options = subset.Options()
        # Hints only adjust the outlines to the pixels of low-resolution screens
        options.hinting = False
        # FontForge's record of when it made the font, which browsers don't use
        options.drop_tables.append("FFTM")
        # Keep the copyright and license notices, which the GPL asks copies to keep
        options.name_IDs = ["*"]
        subsetter = subset.Subsetter(options)
        subsetter.populate(unicodes=wanted)
        subsetter.subset(font)
        font.flavor = "woff2"
        path = f"fonts/{name}-{group}.woff2"
        font.save(f"static/{path}")
        css += f"""
@font-face {{
    font-family: {family};
    font-weight: {weight};
    font-style: {style};
    font-display: swap;
    src: url({path});
    unicode-range: {unicode_range};
}}
"""

open("assets/fonts.css", "w").write(css)
